 const createBudget=async(send:boolean)=>{if(!mutationsEnabled){setError("재정 변경 기능은 현재 잠겨 있습니다.");return;}if(!supabase)return;setSaving(true);setError("");try{const valid=budgetLines.filter(x=>x.account_id&&Number(x.planned_amount)>0);let budgetId=editingBudgetId;if(editingBudgetId){const r=await supabase.rpc("mrpst_update_budget_draft",{target_budget:editingBudgetId,p_year:Number(budgetYear),p_title:budgetTitle.trim(),p_fund_id:budgetFund,p_lines:valid.map(x=>({account_id:x.account_id,planned_amount:Number(x.planned_amount),notes:x.notes||null}))});if(r.error)throw r.error;}else{const r=await supabase.rpc("mrpst_create_budget",{p_year:Number(budgetYear),p_title:budgetTitle.trim(),p_fund_id:budgetFund,p_lines:valid.map(x=>({account_id:x.account_id,planned_amount:Number(x.planned_amount),notes:x.notes||null}))});if(r.error)throw r.error;if(!r.data)throw new Error("예산 생성 ID를 반환받지 못했습니다.");budgetId=r.data;}if(send){const sub=await supabase.rpc("mrpst_submit_budget",{target_budget:budgetId});if(sub.error)throw sub.error;const {data:submitted,error:verifyError}=await supabase.from("finance_budgets").select("id,status").eq("id",budgetId).maybeSingle();if(verifyError)throw verifyError;if(!submitted||submitted.id!==budgetId||submitted.status!=="submitted")throw new Error("예산 제출 상태를 확인할 수 없습니다.");}setNotice(send?"예산안을 저장하고 결재 요청했습니다.":editingBudgetId?"임시 예산안을 수정했습니다.":"예산안을 임시 저장했습니다.");setShowBudget(false);setEditingBudgetId("");setBudgetTitle("");setBudgetLines([{account_id:"",planned_amount:"",notes:""}]);await load();}catch(x:any){setError(x.message??"예산 저장에 실패했습니다.");}finally{setSaving(false);}};
